describe("sseUrl", () => {
  beforeEach(() => {
    localStorage.clear();
  });

  it("constructs URL with api_key param", () => {
    localStorage.setItem("erock_api_key", "key123");
    const url = sseUrl("/pipeline/runs/1/progress");
    expect(url).toContain("/api/v1/pipeline/runs/1/progress");
